// Load the EII scoring prompt
const fs = require('fs');
const path = require('path');

// Read the prompt file
const promptPath = path.join(__dirname, '../prompts/score_prompt.txt');
let prompt;

try {
  prompt = fs.readFileSync(promptPath, 'utf8');
} catch (error) {
  // Fallback prompt if file not found
  prompt = `You are an expert analyst tasked with evaluating articles for "expertise inflation" - the tendency for AI-related content to exhibit overconfidence, excessive jargon, and inflated claims of expertise.

Analyze the following article and score it on these five dimensions (1-10 scale):

**CONFIDENCE INFLATION (1-10):**
- 1-3: Humble, acknowledges limitations, uses hedging language
- 4-6: Moderate confidence, some definitive statements but balanced
- 7-8: High confidence, frequent definitive claims, minimal uncertainty
- 9-10: Extreme overconfidence, absolute statements, dismisses alternatives

**JARGON DENSITY (1-10):**
- 1-3: Plain language, minimal technical terms, concepts well-explained
- 4-6: Some technical language but accessible, good explanations
- 7-8: Heavy jargon, buzzwords, assumes expert knowledge
- 9-10: Incomprehensible jargon wall, buzzword bingo, obfuscating

**SELF-REFERENCE/AUTHORITY (1-10):**
- 1-3: Minimal self-promotion, cites others, collaborative tone
- 4-6: Some personal expertise mentioned, balanced citations
- 7-8: Frequent self-citation, emphasizes own authority/experience
- 9-10: Extreme self-promotion, dismisses others, "guru" positioning

**ORIGINALITY CLAIMS (1-10):**
- 1-3: Builds on existing work, gives credit, incremental insights
- 4-6: Some novel ideas mixed with established concepts
- 7-8: Claims significant breakthroughs, overstates novelty
- 9-10: Claims to have "cracked the code", revolutionary breakthrough

**HUMOR/SELF-AWARENESS (1-10):**
- 1-3: No humor, takes itself very seriously, lacks perspective
- 4-6: Occasional light moments, some self-awareness
- 7-8: Good humor, acknowledges absurdities, self-deprecating
- 9-10: Satirical, highly self-aware, embraces the absurd

Return your analysis as a JSON object with this exact structure:

{
  "scores": {
    "confidence": <1-10 integer>,
    "jargon_density": <1-10 integer>, 
    "self_reference": <1-10 integer>,
    "originality": <1-10 integer>,
    "humor_rating": <1-10 integer>
  },
  "analysis": {
    "overall_eii_score": <calculated average of first 4 scores>,
    "key_phrases": ["<notable overconfident phrase>", "<jargon example>", "<self-reference example>"],
    "tone_summary": "<2-3 sentence summary of the article's tone and approach>",
    "inflation_type": "<primary type: 'Technical Guru', 'Thought Leader', 'Breakthrough Claimer', 'Jargon Bomber', or 'Balanced'>"
  }
}

---

ARTICLE TO ANALYZE:

[INSERT ARTICLE TEXT HERE]`;
}

return [{ json: { prompt } }];

// Parse LLM responses and prepare data for DynamoDB
const crypto = require('crypto');
const openaiResult = $('OpenAI Analysis').first();
const anthropicResult = $('Anthropic Analysis').first();
const originalUrl = $('Webhook Trigger').first().$json.url;
const scrapedData = $('Firecrawl Scrape').first().$json.data;

// Extract JSON from OpenAI response
let openaiScores = null;
try {
  const openaiContent = openaiResult.$json.choices[0].message.content;
  const jsonStart = openaiContent.indexOf('{');
  const jsonEnd = openaiContent.lastIndexOf('}') + 1;
  if (jsonStart !== -1 && jsonEnd > jsonStart) {
    openaiScores = JSON.parse(openaiContent.substring(jsonStart, jsonEnd));
  }
} catch (error) {
  console.log('Failed to parse OpenAI response:', error);
}

// Extract JSON from Anthropic response
let anthropicScores = null;
try {
  const anthropicContent = anthropicResult.$json.content[0].text;
  const jsonStart = anthropicContent.indexOf('{');
  const jsonEnd = anthropicContent.lastIndexOf('}') + 1;
  if (jsonStart !== -1 && jsonEnd > jsonStart) {
    anthropicScores = JSON.parse(anthropicContent.substring(jsonStart, jsonEnd));
  }
} catch (error) {
  console.log('Failed to parse Anthropic response:', error);
}

// Use OpenAI as primary, Anthropic as fallback
const finalScores = openaiScores || anthropicScores;

if (!finalScores) {
  throw new Error('Failed to parse any LLM response');
}

// Generate unique article ID
const articleId = crypto.randomUUID();
const timestamp = new Date().toISOString();
const urlHost = new URL(originalUrl).hostname;

// Prepare DynamoDB item (single table design)
const dynamoItem = {
  article_id: articleId,
  title: scrapedData.title || 'Untitled',
  source: urlHost,
  url: originalUrl,
  author: scrapedData.author || null,
  content: scrapedData.markdown,
  published_at: scrapedData.publishedTime || timestamp,
  scored_at: timestamp,

  // Scores embedded in the same item (NoSQL approach)
  scores: {
    confidence: finalScores.scores.confidence,
    jargon_density: finalScores.scores.jargon_density,
    self_reference: finalScores.scores.self_reference,
    originality: finalScores.scores.originality,
    humor_rating: finalScores.scores.humor_rating,
    overall_eii_score: finalScores.analysis.overall_eii_score
  },

  // Analysis data
  analysis: {
    tone_summary: finalScores.analysis.tone_summary,
    inflation_type: finalScores.analysis.inflation_type,
    key_phrases: finalScores.analysis.key_phrases,
    model_used: openaiScores ? 'gpt-4' : 'claude-3-haiku'
  }
};

return [{ json: dynamoItem }];

